patches.before:
/* Ciudad Juárez is a pre-opening page, not an operating branch profile. */
.ciudad-juarez-opening .opening-skip-link {
  position: fixed;
  z-index: 100;
  top: 12px;
  left: 12px;
  padding: 10px 14px;
  background: var(--cream);
  color: var(--ink);
  transform: translateY(-160%);
}
.ciudad-juarez-opening .opening-skip-link:focus { transform: translateY(0); }
.ciudad-juarez-opening .opening-page-header { grid-template-columns: minmax(0, 1fr) auto; }
.ciudad-juarez-opening .opening-page-nav { display: flex; align-items: center; gap: 1.2rem; font-size: .82rem; font-weight: 700; }
.ciudad-juarez-opening .opening-page-nav > a:not(.nav-cta) { color: var(--muted); }
.ciudad-juarez-opening .opening-page-nav > a:not(.nav-cta):hover { color: var(--cream); }
.ciudad-juarez-opening .opening-page-hero { min-height: min(760px, calc(100svh - 76px)); }
.ciudad-juarez-opening .opening-page-hero > img { object-position: 50% 48%; }
.ciudad-juarez-opening .opening-page-hero-copy {
  position: relative;
  z-index: 2;
  display: flex;
  min-height: min(760px, calc(100svh - 76px));
  max-width: 920px;
  flex-direction: column;
  justify-content: flex-end;
  padding: clamp(7rem, 14vw, 12rem) clamp(1.3rem, 5vw, 5rem) clamp(4rem, 7vw, 7rem);
}
.ciudad-juarez-opening .opening-page-hero-copy h1 { margin-bottom: 1rem; font-size: clamp(3.2rem, 7vw, 7rem); }
.ciudad-juarez-opening .opening-page-hero-copy > p:not(.eyebrow) { max-width: 620px; color: #e5d9cb; font-size: clamp(1rem, 1.6vw, 1.25rem); }
.ciudad-juarez-opening .opening-page-introduction { display: grid; grid-template-columns: minmax(0, 1fr) minmax(260px, .72fr); gap: clamp(2rem, 8vw, 9rem); align-items: end; }
.ciudad-juarez-opening .opening-page-introduction h2 { margin: 0; }
.ciudad-juarez-opening .opening-page-introduction > div:last-child { color: var(--muted); }
.ciudad-juarez-opening .opening-page-introduction > div:last-child > p { margin-top: 0; max-width: 38ch; }
.ciudad-juarez-opening .opening-page-following { align-items: center; }
.ciudad-juarez-opening .opening-page-following > p { max-width: 34ch; color: rgba(10, 8, 7, .78); }
@media (max-width: 700px) {
  .ciudad-juarez-opening .opening-page-header { min-height: 68px; }
  .ciudad-juarez-opening .opening-page-nav { gap: .75rem; font-size: .75rem; }
  .ciudad-juarez-opening .opening-page-hero,
  .ciudad-juarez-opening .opening-page-hero-copy { min-height: min(680px, calc(100svh - 68px)); }
  .ciudad-juarez-opening .opening-page-introduction { grid-template-columns: 1fr; }
}
@media (prefers-reduced-motion: reduce) {
  .ciudad-juarez-opening .opening-skip-link { transition: none; }
}

patches.after:
/* Pre-opening variation of the existing branch shell; no operating details implied. */
.ciudad-juarez-opening .hh-arrival { background: #34180f; }
.ciudad-juarez-opening .hh-welcome { padding-top: 150px; }
.ciudad-juarez-opening .hh-invitation { max-width: 6.5em; }
.ciudad-juarez-opening .hh-cantina-photo::before { inset: 0; background: #34180f; filter: none; opacity: 1; }
.ciudad-juarez-opening .hh-cantina-photo::after {
  background: linear-gradient(90deg, transparent 28%, #34180f44 48%, #34180f 86%);
  opacity: 1;
}
.ciudad-juarez-opening .hh-cantina-photo img { width: 68%; object-position: 50% 44%; }
.ciudad-juarez-opening .hh-welcome-actions { gap: 12px; }
.ciudad-juarez-opening .hh-welcome-actions .hh-reserve { justify-content: space-between; gap: 22px; }
.cj-hero-note { max-width: 29em; margin-top: 24px; font-size: 13px; line-height: 1.7; color: #fff4debf; }
.cj-opening {
  display: grid; grid-template-columns: 1fr 1fr; align-items: center;
  gap: clamp(40px, 8vw, 130px); padding: clamp(70px, 8vw, 120px) var(--site-gutter);
  background: var(--paper); color: var(--ink); scroll-margin-top: 40px; outline: none;
}
.cj-opening-heading h2 { color: var(--wine); font: 400 clamp(76px, 7vw, 112px)/.94 var(--landing-display); }
.cj-opening-heading > p { margin-top: 24px; font-size: 13px; }
.cj-opening-copy { max-width: 34em; font-size: clamp(16px, 1.4vw, 19px); line-height: 1.7; }
.cj-opening-copy > p + p { margin-top: 20px; }
.cj-text-link { display: inline-flex; align-items: center; gap: 24px; min-height: 48px; margin-top: 26px; color: var(--wine); font-size: 14px; font-weight: 700; }
.cj-footer .bf-main { padding-bottom: 60px; }
.cj-footer .bf-place { max-width: 9ch; line-height: .97; }
.cj-next { margin-top: 34px; font-size: 14px; line-height: 1.6; }
.cj-next > p:first-child { margin-bottom: 10px; color: var(--local-onBrand); font-size: 12px; }
.cj-next > p:last-child { margin-top: 8px; font-size: 12px; }
.ciudad-juarez-opening :is(.hh-header a, .hh-welcome a, .cj-text-link, .bf-navigation a) { transition: background-color 160ms ease, color 160ms ease; }
@media (min-width: 761px) and (max-width: 1100px) {
  .ciudad-juarez-opening .hh-welcome { width: 50%; padding-right: 30px; }
  .ciudad-juarez-opening .hh-invitation { font-size: clamp(76px, 8vw, 100px); }
  .ciudad-juarez-opening .hh-welcome-actions .hh-reserve { width: 100%; min-height: 56px; }
}
@media (max-width: 760px) {
  .ciudad-juarez-opening .hh-arrival { min-height: 920px; min-height: max(850px, 100svh); }
  .ciudad-juarez-opening .hh-welcome { width: 100%; min-height: inherit; padding: 120px 20px 30px; }
  .ciudad-juarez-opening .hh-locality { margin-top: 0; }
  .ciudad-juarez-opening .hh-invitation { max-width: 5em; margin-top: 24px; font-size: clamp(76px, 19vw, 104px); }
  .ciudad-juarez-opening .hh-cantina-photo img { width: 100%; object-position: 20% 50%; mask-image: none; -webkit-mask-image: none; }
  .ciudad-juarez-opening .hh-cantina-photo::after { background: linear-gradient(#1b0e0bc9, #24100d99 32%, #34180f38 52%, #34180fe8 80%, #34180f); }
  .ciudad-juarez-opening .hh-welcome-actions { margin-top: auto; padding-top: 50px; }
  .ciudad-juarez-opening .hh-welcome-actions .hh-reserve { width: 100%; min-height: 56px; }
  .cj-hero-note { margin-top: 17px; font-size: 12px; }
  .cj-opening { grid-template-columns: 1fr; gap: 34px; padding: 62px 20px 64px; }
  .cj-opening-heading h2 { font-size: clamp(70px, 20vw, 100px); }
  .cj-opening-copy { font-size: 16px; }
  .cj-footer .bf-main { padding-bottom: 42px; }
  .cj-footer .bf-identity { min-height: 0; padding-bottom: 34px; }
  .cj-footer .bf-place { max-width: none; font-size: clamp(60px, 19vw, 100px); }
}
@media (prefers-reduced-motion: reduce) {
  .ciudad-juarez-opening :is(.hh-header a, .hh-welcome a, .cj-text-link, .bf-navigation a) { transition: none; }
}
